import { describe, expect, test } from "bun:test";
import { generateDjangoModels } from "./django";
import {
	SCHEMA_CODE_FIXTURES,
	awkwardNamesDesign,
	blogDesign,
	minimalDesign,
	vectorDesign,
} from "./fixtures";

describe("generateDjangoModels", () => {
	test("minimal fixture snapshot", () => { expect(codeFor(SCHEMA_CODE_FIXTURES.minimal)).toMatchInlineSnapshot(`
	  "# Generated schema code. Requires Django 6.1 and PostgreSQL.
	  from django.db import models

	  # Migration notes:
	  # - Django uses GENERATED BY DEFAULT AS IDENTITY; PostgreSQL uses GENERATED ALWAYS AS
	  #   IDENTITY.
	  #   Affected columns: users.id.
	  # - Django chooses the constraint name for unique=True fields.
	  #   Affected columns: users.email.
	  # - Django's PostgreSQL backend adds a pattern_ops index for unique text fields.
	  #   Affected columns: users.email.


	  class User(models.Model):
	      id = models.BigAutoField(primary_key=True)
	      email = models.TextField(unique=True)
	      display_name = models.TextField(null=True)

	      class Meta:
	          db_table = "users"
	  "
	`); });
	test("blog fixture snapshot", () => { expect(codeFor(SCHEMA_CODE_FIXTURES.blog)).toMatchInlineSnapshot(`
	  "# Generated schema code. Requires Django 6.1 and PostgreSQL.
	  from django.contrib.postgres.fields import ArrayField
	  from django.contrib.postgres.indexes import BrinIndex, GinIndex, HashIndex, OpClass
	  from django.db import models
	  from django.db.models.functions import Now

	  # Migration notes:
	  # - CREATE TYPE "user_role" AS ENUM ('member', 'editor', 'admin'). Use RunSQL to alter
	  #   each listed column to the named enum type.
	  #   Affected columns: users.role.
	  # - Django uses GENERATED BY DEFAULT AS IDENTITY; PostgreSQL uses GENERATED ALWAYS AS
	  #   IDENTITY.
	  #   Affected columns: users.id, profiles.id, comments.id, tags.id, post_tags.id.
	  # - Django chooses the constraint name for unique=True fields.
	  #   Affected columns: users.email, tags.name.
	  # - Django's PostgreSQL backend adds a pattern_ops index for unique text fields.
	  #   Affected columns: users.email, tags.name.
	  # - Django uses STATEMENT_TIMESTAMP(); PostgreSQL CURRENT_TIMESTAMP is transaction-start
	  #   time.
	  #   Affected columns: users.created_at, posts.created_at, post_tags.added_at.
	  # - Foreign-key constraint names are chosen by Django, not copied from PostgreSQL.
	  #   Affected columns: profiles.user_id, posts.author_id, posts.editor_id,
	  #   comments.post_id, comments.parent_id, post_tags.post_id, post_tags.tag_id.
	  # - Django creates DEFERRABLE INITIALLY DEFERRED foreign keys; the PostgreSQL preview
	  #   uses immediate enforcement.
	  #   Affected columns: profiles.user_id, posts.author_id, posts.editor_id,
	  #   comments.post_id, comments.parent_id, post_tags.post_id, post_tags.tag_id.
	  # - ForeignKey fields disable Django's implicit index because the PostgreSQL preview
	  #   defines none.
	  #   Affected columns: posts.author_id, posts.editor_id, comments.post_id,
	  #   comments.parent_id, post_tags.post_id, post_tags.tag_id.
	  # - ON UPDATE CASCADE requires RunSQL.
	  #   Affected columns: comments.post_id.
	  # - ON DELETE RESTRICT requires RunSQL; Django's DO_NOTHING emits NO ACTION.
	  #   Affected columns: post_tags.tag_id.
	  # Unique index posts_title_editor_id_idx is represented by UniqueConstraint; PostgreSQL
	  #   catalogs it as a constraint rather than a standalone index.


	  class UserRole(models.TextChoices):
	      MEMBER = "member"
	      EDITOR = "editor"
	      ADMIN = "admin"


	  class User(models.Model):
	      id = models.BigAutoField(primary_key=True)
	      email = models.CharField(max_length=255, unique=True)
	      display_name = models.TextField(null=True)
	      role = models.CharField(db_default="member", choices=UserRole.choices, max_length=6)
	      created_at = models.DateTimeField(db_default=Now())

	      class Meta:
	          db_table = "users"
	          indexes = (
	              BrinIndex(
	                  fields=["created_at"],
	                  name="users_created_at_idx",
	                  pages_per_range=32,
	              ),
	          )


	  class Profile(models.Model):
	      id = models.BigAutoField(primary_key=True)
	      user = models.OneToOneField(
	          "User",
	          models.DB_CASCADE,
	          related_name="profile",
	          db_column="user_id",
	      )
	      bio = models.TextField(null=True)
	      birthday = models.DateField(null=True)

	      class Meta:
	          db_table = "profiles"


	  class Post(models.Model):
	      id = models.UUIDField(
	          primary_key=True,
	          db_default=models.Func(
	              function="gen_random_uuid",
	              output_field=models.UUIDField(),
	          ),
	      )
	      author = models.ForeignKey(
	          "User",
	          models.DB_CASCADE,
	          related_name="author_posts",
	          db_column="author_id",
	          db_index=False,
	      )
	      editor = models.ForeignKey(
	          "User",
	          models.DB_SET_NULL,
	          related_name="editor_posts",
	          db_column="editor_id",
	          null=True,
	          db_index=False,
	      )
	      title = models.TextField()
	      slug = models.CharField(max_length=120)
	      body = models.TextField(null=True)
	      keywords = ArrayField(models.TextField(), null=True)
	      published = models.BooleanField(db_default=False)
	      rating = models.DecimalField(max_digits=3, decimal_places=1, null=True)
	      metadata = models.JSONField(db_default={})
	      created_at = models.DateTimeField(db_default=Now())
	      tags = models.ManyToManyField(
	          "Tag",
	          through="PostTag",
	          through_fields=("post", "tag"),
	          related_name="posts",
	      )

	      class Meta:
	          db_table = "posts"
	          constraints = (
	              models.UniqueConstraint(
	                  fields=["author", "slug"],
	                  name="posts_author_slug_key",
	              ),
	              models.UniqueConstraint(
	                  fields=["title", "editor"],
	                  name="posts_title_editor_id_idx",
	                  nulls_distinct=False,
	              ),
	          )
	          indexes = (
	              models.Index(
	                  models.F("author"),
	                  models.F("created_at").desc(nulls_last=True),
	                  name="posts_author_id_created_at_idx",
	                  include=["title"],
	              ),
	              GinIndex(models.F("keywords"), name="posts_keywords_gin"),
	              GinIndex(
	                  OpClass(models.F("metadata"), name="jsonb_path_ops"),
	                  name="posts_metadata_idx",
	                  fastupdate=False,
	              ),
	              HashIndex(fields=["slug"], name="posts_slug_idx"),
	          )


	  class Comment(models.Model):
	      id = models.BigAutoField(primary_key=True)
	      post = models.ForeignKey(
	          "Post",
	          models.DB_CASCADE,
	          related_name="comments",
	          db_column="post_id",
	          db_index=False,
	      )
	      parent = models.ForeignKey(
	          "Comment",
	          models.DB_SET_NULL,
	          related_name="children",
	          db_column="parent_id",
	          null=True,
	          db_index=False,
	      )
	      body = models.TextField()

	      class Meta:
	          db_table = "comments"


	  class Tag(models.Model):
	      id = models.BigAutoField(primary_key=True)
	      name = models.CharField(max_length=64, unique=True)

	      class Meta:
	          db_table = "tags"


	  class PostTag(models.Model):
	      id = models.BigAutoField(primary_key=True)
	      post = models.ForeignKey(
	          "Post",
	          models.DB_CASCADE,
	          related_name="post_tags",
	          db_column="post_id",
	          db_index=False,
	      )
	      tag = models.ForeignKey(
	          "Tag",
	          models.DO_NOTHING,
	          related_name="post_tags",
	          db_column="tag_id",
	          db_index=False,
	      )
	      added_at = models.DateTimeField(db_default=Now())

	      class Meta:
	          db_table = "post_tags"
	          constraints = (
	              models.UniqueConstraint(fields=["post", "tag"], name="post_tags_pair_key"),
	          )
	  "
	`); });
	test("vector fixture snapshot", () => { expect(codeFor(SCHEMA_CODE_FIXTURES.vector)).toMatchInlineSnapshot(`
	  "# Generated schema code. Requires Django 6.1 and PostgreSQL.
	  from django.contrib.postgres.indexes import OpClass
	  from django.db import models
	  from pgvector.django import (
	      BitField,
	      HalfVectorField,
	      HnswIndex,
	      IvfflatIndex,
	      SparseVectorField,
	      VectorField,
	  )

	  # Migration notes:
	  # - pgvector columns require VectorExtension() in a migration.
	  #   Affected columns: documents.embedding, documents.summary_embedding,
	  #   documents.keywords_embedding.
	  # - Django uses GENERATED BY DEFAULT AS IDENTITY; PostgreSQL uses GENERATED ALWAYS AS
	  #   IDENTITY.
	  #   Affected columns: documents.id.
	  # Index documents_keywords_embedding_idx exceeds Django's 30-character name limit;
	  #   Django uses documents_keywords_embe_1y5shd.


	  class PostgreSQLTypeField(models.Field):
	      def __init__(self, *args, pg_type, **kwargs):
	          self.pg_type = pg_type
	          super().__init__(*args, **kwargs)

	      def db_type(self, connection):
	          return self.pg_type

	      def deconstruct(self):
	          name, path, args, kwargs = super().deconstruct()
	          kwargs["pg_type"] = self.pg_type
	          return name, path, args, kwargs


	  class Document(models.Model):
	      id = models.BigAutoField(primary_key=True)
	      content = models.TextField()
	      embedding = VectorField(dimensions=1536)
	      summary_embedding = HalfVectorField(dimensions=768, null=True)
	      keywords_embedding = SparseVectorField(dimensions=30000, null=True)
	      signature = BitField(length=256, null=True)

	      class Meta:
	          db_table = "documents"
	          indexes = (
	              HnswIndex(
	                  OpClass(models.F("embedding"), name="vector_cosine_ops"),
	                  name="documents_embedding_idx",
	                  m=16,
	                  ef_construction=64,
	              ),
	              IvfflatIndex(
	                  OpClass(models.F("summary_embedding"), name="halfvec_l2_ops"),
	                  name="documents_summary_ivfflat",
	                  lists=100,
	              ),
	              HnswIndex(
	                  OpClass(models.F("keywords_embedding"), name="sparsevec_ip_ops"),
	                  name="documents_keywords_embe_1y5shd",
	              ),
	              HnswIndex(
	                  OpClass(models.F("signature"), name="bit_hamming_ops"),
	                  name="documents_signature_idx",
	              ),
	          )
	  "
	`); });
	test("typeCatalog fixture snapshot", () => { expect(codeFor(SCHEMA_CODE_FIXTURES.typeCatalog)).toMatchInlineSnapshot(`
	  "# Generated schema code. Requires Django 6.1 and PostgreSQL.
	  from decimal import Decimal

	  from django.contrib.postgres.fields import ArrayField
	  from django.db import models
	  from django.db.models import Value
	  from django.db.models.functions import Cast
	  from pgvector.django import BitField, HalfVectorField, SparseVectorField, VectorField

	  # Migration notes:
	  # - pgvector columns require VectorExtension() in a migration.
	  #   Affected columns: type_catalog.vector_value, type_catalog.halfvec_value,
	  #   type_catalog.sparsevec_value.
	  # - CREATE TYPE "mood" AS ENUM ('happy', 'sad', 'in-between'). Use RunSQL to alter each
	  #   listed column to the named enum type.
	  #   Affected columns: type_catalog.mood_value, type_catalog.mood_history.
	  # - Django uses GENERATED BY DEFAULT AS IDENTITY; PostgreSQL uses GENERATED ALWAYS AS
	  #   IDENTITY.
	  #   Affected columns: type_catalog.id.


	  class PostgreSQLTypeField(models.Field):
	      def __init__(self, *args, pg_type, **kwargs):
	          self.pg_type = pg_type
	          super().__init__(*args, **kwargs)

	      def db_type(self, connection):
	          return self.pg_type

	      def deconstruct(self):
	          name, path, args, kwargs = super().deconstruct()
	          kwargs["pg_type"] = self.pg_type
	          return name, path, args, kwargs


	  class Mood(models.TextChoices):
	      HAPPY = "happy"
	      SAD = "sad"
	      IN_BETWEEN = "in-between"


	  class TypeCatalog(models.Model):
	      id = models.BigAutoField(primary_key=True)
	      integer_value = models.IntegerField(null=True)
	      smallint_value = models.SmallIntegerField(null=True)
	      text_value = models.TextField(null=True)
	      varchar_value = models.CharField(max_length=40, null=True)
	      varchar_unbounded = PostgreSQLTypeField(pg_type="character varying", null=True)
	      char_value = PostgreSQLTypeField(pg_type="character(2)", null=True)
	      uuid_value = models.UUIDField(null=True)
	      boolean_value = models.BooleanField(null=True)
	      numeric_value = PostgreSQLTypeField(pg_type="numeric", null=True)
	      money_amount = models.DecimalField(max_digits=12, decimal_places=2, null=True)
	      real_value = PostgreSQLTypeField(pg_type="real", null=True)
	      double_value = models.FloatField(null=True)
	      date_value = models.DateField(null=True)
	      time_value = models.TimeField(null=True)
	      timetz_value = PostgreSQLTypeField(pg_type="timetz", null=True)
	      timestamp_value = PostgreSQLTypeField(pg_type="timestamp", null=True)
	      timestamptz_value = models.DateTimeField(null=True)
	      interval_value = PostgreSQLTypeField(pg_type="interval", null=True)
	      json_value = PostgreSQLTypeField(pg_type="json", null=True)
	      jsonb_value = models.JSONField(null=True)
	      bytea_value = models.BinaryField(null=True)
	      inet_value = PostgreSQLTypeField(pg_type="inet", null=True)
	      cidr_value = PostgreSQLTypeField(pg_type="cidr", null=True)
	      macaddr_value = PostgreSQLTypeField(pg_type="macaddr", null=True)
	      money_value = PostgreSQLTypeField(pg_type="money", null=True)
	      bit_value = BitField(length=8, null=True)
	      vector_value = VectorField(dimensions=3, null=True)
	      halfvec_value = HalfVectorField(dimensions=3, null=True)
	      sparsevec_value = SparseVectorField(dimensions=3, null=True)
	      mood_value = models.CharField(null=True, choices=Mood.choices, max_length=10)
	      mood_history = ArrayField(
	          models.CharField(choices=Mood.choices, max_length=10),
	          null=True,
	      )
	      integer_list = ArrayField(models.IntegerField(), null=True)
	      uuid_list = ArrayField(models.UUIDField(), null=True)
	      integer_default = models.IntegerField(db_default=42)
	      numeric_default = PostgreSQLTypeField(pg_type="numeric", db_default=Decimal("1.50"))
	      text_default = models.TextField(db_default='it\\'s "quoted"')
	      date_default = models.DateField(
	          db_default=Cast(Value("2024-01-31"), output_field=models.DateField()),
	      )

	      class Meta:
	          db_table = "type_catalog"
	  "
	`); });
	test("awkwardNames fixture snapshot", () => { expect(codeFor(SCHEMA_CODE_FIXTURES.awkwardNames)).toMatchInlineSnapshot(`
	  "# Generated schema code. Requires Django 6.1 and PostgreSQL.
	  from django.db import models

	  # Migration notes:
	  # - CREATE TYPE "order-status" AS ENUM ('new', 'in progress', '2nd try', 'None'). Use
	  #   RunSQL to alter each listed column to the named enum type.
	  #   Affected columns: order_items.status.
	  # - Django uses GENERATED BY DEFAULT AS IDENTITY; PostgreSQL uses GENERATED ALWAYS AS
	  #   IDENTITY.
	  #   Affected columns: class.id, order_items.id, OrderItems.id.
	  # - ForeignKey fields disable Django's implicit index because the PostgreSQL preview
	  #   defines none.
	  #   Affected columns: order_items.class_id.
	  # - Foreign-key constraint names are chosen by Django, not copied from PostgreSQL.
	  #   Affected columns: order_items.class_id.
	  # - Django creates DEFERRABLE INITIALLY DEFERRED foreign keys; the PostgreSQL preview
	  #   uses immediate enforcement.
	  #   Affected columns: order_items.class_id.


	  class OrderStatus(models.TextChoices):
	      NEW = "new"
	      IN_PROGRESS = "in progress"
	      FIELD_2ND_TRY = "2nd try"
	      NONE = "None"


	  class Class(models.Model):
	      id = models.BigAutoField(primary_key=True)
	      from_field = models.TextField(db_column="from")
	      import_field = models.TextField(null=True, db_column="import")
	      type_field = models.TextField(null=True, db_column="type")
	      field_2fa_secret = models.TextField(null=True, db_column="2fa_secret")
	      display_name = models.TextField(null=True, db_column="Display Name")
	      user_id = models.IntegerField(null=True)
	      user_id_2 = models.IntegerField(null=True, db_column="userId")

	      class Meta:
	          db_table = "class"


	  class OrderItem(models.Model):
	      id = models.BigAutoField(primary_key=True)
	      class_field = models.ForeignKey(
	          "Class",
	          models.DO_NOTHING,
	          related_name="order_items",
	          db_column="class_id",
	          db_index=False,
	      )
	      status = models.CharField(choices=OrderStatus.choices, max_length=11)

	      class Meta:
	          db_table = "order_items"


	  class OrderItem_2(models.Model):
	      id = models.BigAutoField(primary_key=True)

	      class Meta:
	          db_table = "OrderItems"
	  "
	`); });

	test("maps Django field types, arrays, literals, defaults and enum labels", () => {
		const code = codeFor(SCHEMA_CODE_FIXTURES.typeCatalog);
		expect(code).toContain("models.SmallIntegerField(null=True)");
		expect(code).toContain("ArrayField(models.IntegerField(), null=True)");
		expect(code).toContain("db_default=42");
		expect(code).toContain("class Mood(models.TextChoices):");
		expect(code).toContain("IN_BETWEEN = \"in-between\"");
		expect(code).toContain("models.DateTimeField");
	});

	test("drops default-valued field options and uses native single-column uniqueness", () => {
		const code = codeFor(blogDesign);
		const minimal = codeFor(SCHEMA_CODE_FIXTURES.minimal);
		expect(minimal).toContain('email = models.TextField(unique=True)');
		expect(code).toContain("published = models.BooleanField(db_default=False)");
		expect(code).not.toContain("null=False");
		expect(code).not.toContain("Value(False)");
	});
	test("renders JSON defaults as valid Python literals", () => {
		const design = structuredClone(blogDesign);
		const metadata = design.tables
			.find((table) => table.id === "t_posts")!
			.columns.find((column) => column.id === "c_posts_metadata")!;
		metadata.default = {
			kind: "literal",
			literalType: "json",
			value: '{"enabled":true,"items":[false,null]}',
		};
		const result = generateDjangoModels(design);
		if (!result.ok) throw new Error(result.errors.join("\n"));
		expect(result.code).toContain(
			'metadata = models.JSONField(db_default={"enabled": True, "items": [False, None]})',
		);
	});

	test("makes Python identifiers valid and collision-free while preserving database names", () => {
		const code = codeFor(awkwardNamesDesign);
		expect(code).toContain("class Class(models.Model):");
		expect(code).toContain('from_field = models.TextField(db_column="from")');
		expect(code).toContain('field_2fa_secret = models.TextField(null=True, db_column="2fa_secret")');
		expect(code).toContain("user_id = models.IntegerField(null=True)");
		expect(code).toContain('user_id_2 = models.IntegerField(null=True, db_column="userId")');
	});

	test("uses shared singular model and relationship names", () => {
		const code = codeFor(blogDesign);
		expect(code).toContain("class User(models.Model):");
		expect(code).toContain("class Post(models.Model):");
		expect(code).toContain("class PostTag(models.Model):");
		expect(code).toContain('related_name="author_posts"');
		expect(code).toContain('related_name="editor_posts"');
		expect(code).toContain('related_name="profile"');
		expect(code).toContain('related_name="children"');
		expect(code).toContain('related_name="comments"');
		expect(code).toContain('related_name="posts"');
		expect(code).toContain('related_name="post_tags"');
		expect(code).toContain('tags = models.ManyToManyField(');
	});

	test("groups migration caveats by reason", () => {
		const code = codeFor(blogDesign);
		expect(code.match(/# Migration notes:/g)).toHaveLength(1);
		expect(code.match(/Django uses GENERATED BY DEFAULT AS IDENTITY/g)).toHaveLength(1);
		expect(code).toContain("Affected columns: users.id, profiles.id");
		expect(code).toContain(
			"Django's PostgreSQL backend adds a pattern_ops index for unique text fields.",
		);
		expect(code).toContain("Affected columns: users.email, tags.name.");
	});

	test("renders one-to-many, one-to-one, self, multiple FKs, and explicit M:N through model", () => {
		const code = codeFor(blogDesign);
		expect(code).toContain('author = models.ForeignKey(');
		expect(code).toContain('models.DB_CASCADE,');
		expect(code).toContain('editor = models.ForeignKey(');
		expect(code).toContain('models.DB_SET_NULL,');
		expect(code).toContain('user = models.OneToOneField(');
		expect(code).toContain('parent = models.ForeignKey(');
		expect(code).toContain('through="PostTag"');
		expect(code).toContain('name="posts_author_slug_key"');
		expect(code).toContain('name="post_tags_pair_key"');
	});

	test("maps PostgreSQL and pgvector indexes", () => {
		const blog = codeFor(blogDesign);
		const vector = codeFor(vectorDesign);
		expect(blog).toContain("BrinIndex(");
		expect(blog).toContain("GinIndex(");
		expect(blog).toContain("HashIndex(");
		expect(blog).toContain("OpClass(models.F(\"metadata\"), name=\"jsonb_path_ops\")");
		expect(vector).toContain("HnswIndex(");
		expect(vector).toContain("IvfflatIndex(");
		expect(vector).toContain("VectorField(dimensions=1536");
		expect(vector).toContain("HalfVectorField(dimensions=768");
		expect(vector).toContain("SparseVectorField(dimensions=30000");
		expect(vector).toContain("BitField(length=256");
	});

	test("ends with exactly one newline", () => {
		const code = codeFor(minimalDesign);
		expect(code.endsWith("\n")).toBe(true);
		expect(code.endsWith("\n\n")).toBe(false);
	});
	test("warns when policies need PostgreSQL migrations", () => {
		const design = structuredClone(minimalDesign);
		design.tables[0].policies = [{
			id: "policy", name: "read_rows", command: "SELECT", roles: ["anon"],
			mode: "permissive", using: "true", withCheck: "",
		}];
		expect(codeFor(design)).toContain("# Row-level security and policies are not represented");
	});
});

function codeFor(fixture: (typeof SCHEMA_CODE_FIXTURES)[keyof typeof SCHEMA_CODE_FIXTURES]): string {
	const result = generateDjangoModels(fixture);
	if (!result.ok) throw new Error(result.errors.join("\n"));
	return result.code;
}
